INSERT INTO productos (id, comercio_id, categoria_id, nombre, descripcion, imagen_url, precio_original, precio_reaprovecha, porcentaje_descuento, cantidad_inicial, cantidad_disponible, fecha_vencimiento, hora_limite_retiro, peso_estimado_kg, motivo_oferta, motivo_detalle, estado, ai_priority, ai_priority_label, ai_explanation, ai_suggested_price) VALUES
('prod-1', 'com-2', 'cat-1', 'Yogur Entero Natural Cremoso 1L', 'Yogur bebible entero de primera marca. Lote con 2 días de fecha óptima en perfecto estado organoléptico y refrigeración continua.', 'https://images.unsplash.com/photo-1571212515416-fef01fc43637?w=800&auto=format&fit=crop&q=80', 2500, 1500, 40, 35, 28, '2026-10-05', 'Hoy hasta 19:45 hs', 1, 'Próximo a vencer', 'Fecha óptima en 48 hs. Mantenido rigurosamente a 4°C en cámara de frío.', 'activo', 'alta', 'Prioridad alta', 'Vence en 2 días con 28 unidades. Recomendado 40% OFF para rotar rápidamente.', NULL),
('prod-3', 'com-3', 'cat-1', 'Queso Cremoso Primera Marca Fraccionado 1kg', 'Queso cremoso sin TACC de excelente fundición. Envasado al vacío con etiqueta reglamentaria.', 'https://images.unsplash.com/photo-1624806992066-5ffcf7ca186b?w=800&auto=format&fit=crop&q=80', 7800, 5070, 35, 15, 10, '2026-10-07', 'Hoy hasta 19:30 hs', 1, 'Próximo a vencer', 'Horma fraccionada con 4 días restantes de aptitud recomendada.', 'activo', 'media', 'Prioridad media', 'Vence en 4 días con 10 unidades en stock. Descuento 35% atractivo.', NULL),
('prod-7', 'com-2', 'cat-1', 'Pack Leche Descremada UHT Larga Vida 1L x3', 'Leche fortificada con calcio y vitaminas. Lote próximo a vencer en 6 días en perfecto estado cerrado.', 'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=800&auto=format&fit=crop&q=80', 5700, 3990, 30, 30, 20, '2026-10-09', 'Hoy hasta 19:45 hs', 3, 'Próximo a vencer', 'Pack cerrado de fábrica con 6 días de aptitud bromatológica óptima.', 'activo', 'media', 'Prioridad media', 'Margen de 6 días con buen stock. 30% OFF garantiza salida sostenida.', NULL),
('prod-9', 'com-2', 'cat-1', 'Leche Entera Clásica Sachet 1L', 'Leche entera pasteurizada fresca de tambos de la cuenca Mar y Sierras. Calidad nutricional de primera línea.', 'https://images.unsplash.com/photo-1528750997573-59b89d56f4f7?w=800&auto=format&fit=crop&q=80', 1600, 1120, 30, 30, 22, '2026-10-06', 'Hoy hasta 19:45 hs', 1, 'Próximo a vencer', 'Fecha de consumo preferente en 3 días. Sachet hermético intacto conservado a 3°C.', 'activo', 'media', 'Prioridad media', 'Rotación recomendada antes del recambio semanal de tambo.', NULL),
('prod-10', 'com-3', 'cat-1', 'Queso Rallado Reggianito Estacionado 150g', 'Queso duro tandilero curado por 6 meses. Intenso sabor umami para pastas, risottos y polentas.', '/src/assets/images/queso_rallado_paquete_1791040449361.jpg', 3200, 2400, 25, 20, 15, '2026-10-17', 'Hoy hasta 19:30 hs', 0.15, 'Envase secundario dañado', 'El sobre exterior de cartulina tiene un pliegue rozado en transporte. La bolsa metalizada interior está sellada al vacío 100% íntegra y el alimento es totalmente inocuo y fresco.', 'activo', 'baja', 'Prioridad baja', 'Detalle puramente estético de empaque exterior. 25% OFF para rápida aceptación.', NULL),
('prod-11', 'com-2', 'cat-1', 'Manteca Calidad Extra Primera Marca 200g', 'Elaborada con crema de leche fresca pasteurizada. Textura suave e ideal para repostería o desayunos.', 'https://images.unsplash.com/photo-1589985270826-4b7bb135bc9d?w=800&auto=format&fit=crop&q=80', 2900, 1885, 35, 25, 18, '2026-10-07', 'Hoy hasta 19:45 hs', 0.2, 'Próximo a vencer', 'Lote próximo a fecha límite en 4 días. Envoltorio metalizado sellado sin alteraciones.', 'activo', 'media', 'Prioridad media', 'Oportunidad de ahorro para uso en cocina, horneados o congelado.', NULL),
('prod-12', 'com-6', 'cat-3', 'Salchichas Tipo Viena Tradicionales x6 Unidades', 'Salchichas ahumadas con especias naturales, sin gluten. Aptas para pancho o hervidas en minutos.', 'https://images.unsplash.com/photo-1585325701165-351af916e581?w=800&auto=format&fit=crop&q=80', 2200, 1540, 30, 32, 25, '2026-10-06', 'Hoy hasta 20:15 hs', 0.25, 'Próximo a vencer', 'Paquete termoformado al vacío con precinto de seguridad intacto de fábrica.', 'activo', 'media', 'Prioridad media', '30% de rebaja para liquidar stock previo a nueva recepción frigorífica.', NULL),
('prod-13', 'com-6', 'cat-3', 'Hamburguesas Clásicas de Novillo Tandilero x4', 'Carne picada fresca seleccionada condimentada con sal marina y orégano. Bandeja sellada del día.', '/src/assets/images/hamburguesas_bandeja_1791040462187.jpg', 4600, 2990, 35, 18, 12, '2026-10-05', 'Hoy hasta 20:15 hs', 0.48, 'Baja rotación', 'Excedente de preparación matutina de mostrador. Carne fresca para plancha o parrilla.', 'activo', 'alta', 'Prioridad alta', 'Producto de carnicería fresca con retiro inmediato pactado para hoy.', NULL),
('prod-14', 'com-3', 'cat-3', 'Jamón Cocido Natural Feteado al Vacío 200g', 'Jamón feteado fino de pierna de cerdo seleccionada. Sabor delicado y bajo en sodio.', '/src/assets/images/jamon_cocido_paquete_1791040490477.jpg', 3800, 2280, 40, 22, 16, '2026-10-08', 'Hoy hasta 19:30 hs', 0.2, 'Etiqueta defectuosa', 'La etiqueta autoadhesiva frontal salió torcida de la rotuladora. El termosellado al vacío está 100% hermético e higiénico, garantizando total seguridad bromatológica.', 'activo', 'media', 'Prioridad media', 'Inconveniente de presentación cosmético. Excelente descuento del 40%.', NULL),
('prod-15', 'com-6', 'cat-3', 'Chorizos Criollos Puro Cerdo Tandileros x4 Unidades', 'Elaboración artesanal con tripa natural y especias serranas. Ideales para cocción a la parrilla o sartén.', '/src/assets/images/chorizos_bandeja_1791040475805.jpg', 5200, 3900, 25, 20, 14, '2026-10-07', 'Hoy hasta 20:15 hs', 0.6, 'Baja rotación', 'Lote artesanal preparado en el turno mañana que no completó su cupo de venta.', 'activo', 'baja', 'Prioridad baja', 'Embutido regional clásico de Tandil con 25% OFF para consumidores locales.', NULL),
('prod-16', 'com-6', 'cat-3', 'Pechugas de Pollo Frescas Fileteadas 800g', 'Filetes limpios desgrasados sin piel ni hueso. Listos para milanesas, salteados o a la plancha.', 'https://images.unsplash.com/photo-1604503468506-a8da13d82791?w=800&auto=format&fit=crop&q=80', 5800, 4060, 30, 16, 10, '2026-10-05', 'Hoy hasta 20:15 hs', 0.8, 'Próximo a vencer', 'Bandeja envasada con film respirable para consumo en los próximos 2 días o congelar en frezzer.', 'activo', 'alta', 'Prioridad alta', 'Pollo fresco de granja con 30% OFF para cena rápida y saludable.', NULL),
('prod-17', 'com-7', 'cat-6', 'Gaseosa Cola Línea Clásica Original 1.5L', 'Refresco carbonatado sabor cola en botella PET retornable de fábrica. Gas y sabor intactos.', 'https://images.unsplash.com/photo-1554866585-cd94860890b7?w=800&auto=format&fit=crop&q=80', 2600, 1300, 50, 40, 30, '2026-10-23', 'Hoy hasta 19:45 hs', 1.5, 'Envase o embalaje dañado', 'La botella presenta una abolladura estética en la base por estiba en fardo. El precinto de seguridad y la tapa están 100% sellados de fábrica con total hermetismo.', 'activo', 'alta', 'Prioridad alta', 'Rebaja del 50% por detalle cosmético exterior. Apta 100% para consumo.', NULL),
('prod-18', 'com-5', 'cat-6', 'Jugo Puro de Naranja Exprimido Natural 1L', '100% jugo exprimido en el día sin pulpa añadida ni conservantes. Alto contenido de vitamina C.', 'https://images.unsplash.com/photo-1613478223719-2ab802602423?w=800&auto=format&fit=crop&q=80', 3400, 2040, 40, 22, 15, '2026-10-05', 'Hoy hasta 19:15 hs', 1, 'Próximo a vencer', 'Elaborado artesanalmente en la mañana de hoy. Debe mantenerse refrigerado y consumirse en 48 hs.', 'activo', 'alta', 'Prioridad alta', 'Bebida natural pura sin agregados químicos. 40% OFF para consumo diario.', NULL),
('prod-19', 'com-7', 'cat-6', 'Agua Saborizada Pomelo Rosado Sin Gas 1.5L', 'Bebida con jugo natural de pomelo, baja en calorías y con vitaminas B3 y B6.', '/src/assets/images/agua_pomelo_botella_1791040515622.jpg', 2100, 1575, 25, 30, 24, '2026-10-21', 'Hoy hasta 19:45 hs', 1.5, 'Baja rotación', 'Sobre-stock estacional de distribuidora. Envase y sello impecables.', 'activo', 'baja', 'Prioridad baja', 'Precio accesible para hidratación familiar cotidiana.', NULL),
('prod-20', 'com-2', 'cat-6', 'Bebida Láctea Chocolatada Fortificada 1L', 'Leche chocolatada lista para tomar fría o caliente. Enriquecida con hierro y zinc.', '/src/assets/images/chocolatada_botella_1791292649950.jpg', 2800, 1820, 35, 28, 20, '2026-10-08', 'Hoy hasta 19:45 hs', 1, 'Próximo a vencer', 'Tetra brik original sellado con 5 días para su consumo óptimo.', 'activo', 'media', 'Prioridad media', 'Ideal para meriendas de niños con 35% de descuento directo.', NULL),
('prod-8', 'com-9', 'cat-5', 'Ravioles Frescos de Ricota y Nuez 500g', 'Pasta fresca artesanal elaborada en el día. Masa al huevo, lista para hervir 3 minutos.', '/src/assets/images/ravioles_bandeja_1791040408064.jpg', 4200, 2520, 40, 16, 9, '2026-10-06', 'Hoy hasta 19:30 hs', 0.5, 'Próximo a vencer', 'Pasta fresca con 3 días restantes. Descuento 40% para cena o congelado.', 'activo', 'media', 'Prioridad media', 'Elaboración del día de fábrica tandilera con 40% OFF.', NULL),
('prod-21', 'com-8', 'cat-5', 'Fideos Guiseros Tirabuzón de Trigo Candeal 500g', 'Pasta seca italiana de sémola de trigo duro. Cocción al dente 8 minutos.', '/src/assets/images/fideos_paquete_1791040501949.jpg', 1800, 1260, 30, 40, 32, '2026-11-17', 'Hoy hasta 20:45 hs', 0.5, 'Envase o embalaje dañado', 'La caja de cartón colectiva sufrió un roce superficial. El paquete de celofán interior está herméticamente sellado de fábrica; el alimento es 100% puro y seguro.', 'activo', 'baja', 'Prioridad baja', 'Alimento básico no perecedero con excelente descuento por detalle en caja exterior.', NULL),
('prod-22', 'com-8', 'cat-5', 'Arroz Largo Fino Selección 00000 1kg', 'Arroz blanco de grano entero seleccionado que no se pasa ni se pega. Ideal para guisos y ensaladas.', 'https://images.unsplash.com/photo-1586201375761-83865001e31c?w=800&auto=format&fit=crop&q=80', 2400, 1920, 20, 35, 25, '2026-12-02', 'Hoy hasta 20:45 hs', 1, 'Baja rotación', 'Excedente de pedido mayorista en depósito de supermercado.', 'activo', 'baja', 'Prioridad baja', '20% OFF para aliviar espacio en góndola de almacén.', NULL),
('prod-23', 'com-8', 'cat-5', 'Galletitas Dulces con Chips de Chocolate 350g', 'Galletitas crocantes con chips de chocolate semiamargo y vainilla. Ideales para el café o merienda.', 'https://images.unsplash.com/photo-1499636136210-6f4ee915583e?w=800&auto=format&fit=crop&q=80', 2900, 1885, 35, 24, 18, '2026-10-15', 'Hoy hasta 20:45 hs', 0.35, 'Problema de presentación', 'Solapa del empaque exterior con pliegue asimétrico de termosellado. El contenido interior se mantiene totalmente crujiente, sellado e inocuo.', 'activo', 'media', 'Prioridad media', 'Detalle puramente cosmético de empaque. Descuento tentador del 35%.', NULL),
('prod-24', 'com-2', 'cat-5', 'Cereales Granola Crocante con Miel y Almendras 400g', 'Copos de avena tostados al horno con miel pura de Tandil, almendras fileteadas y semillas de chía.', '/src/assets/images/granola_bolsa_1791040423900.jpg', 4200, 3150, 25, 20, 16, '2026-10-28', 'Hoy hasta 19:45 hs', 0.4, 'Baja rotación', 'Mix artesanal en bolsa doypack con cierre hermético ziploc sin abrir.', 'activo', 'baja', 'Prioridad baja', 'Desayuno saludable serrano con 25% de rebaja directa.', NULL),
('prod-25', 'com-8', 'cat-5', 'Conservas de Arvejas y Choclo Pack x2 Latas 300g', 'Granos tiernos en salmuera ligera sin conservantes artificiales. Listos para ensaladas o tartas.', '/src/assets/images/conservas_pack_latas_1791292668739.jpg', 2500, 1500, 40, 30, 22, '2026-11-02', 'Hoy hasta 20:45 hs', 0.6, 'Envase o embalaje dañado', 'Lata con leve roce superficial de pintura durante el paletizado. El envase no tiene ninguna fisura ni pérdida de vacío; alimento 100% estéril y apto.', 'activo', 'media', 'Prioridad media', 'Excelente oportunidad para armar despensa a 40% de descuento.', NULL),
('prod-26', 'com-9', 'cat-5', 'Salsa de Tomate Frito con Albahaca Fresca 500g', 'Salsa espesa cocinada a fuego lento con aceite de oliva extra virgen y hojas de albahaca recién cosechadas.', '/src/assets/images/salsa_tomate_frasco_1791040435783.jpg', 2300, 1610, 30, 28, 20, '2026-10-18', 'Hoy hasta 19:30 hs', 0.5, 'Etiqueta defectuosa', 'Etiqueta de papel ligeramente desalineada en la línea de pegado. La botella de vidrio y el precinto de botón están 100% herméticos y seguros.', 'activo', 'media', 'Prioridad media', 'Salsa gourmet casera para acompañar pastas del fin de semana.', NULL),
('prod-2', 'com-1', 'cat-2', 'Medialunas de Manteca Artesanales x6', 'Horneadas hoy a primera hora en Tandil. Excedente del turno mañana, crujientes con almíbar artesanal.', 'https://images.unsplash.com/photo-1555507036-ab1f4038808a?w=800&auto=format&fit=crop&q=80', 3200, 1600, 50, 20, 12, '2026-10-04', 'Hoy hasta 20:15 hs', 0.45, 'Próximo a vencer', 'Producto de panadería fresca horneado hoy para consumir antes de mañana.', 'activo', 'alta', 'Prioridad alta', 'Liquidación 50% para retiro hoy antes del cierre.', NULL),
('prod-5', 'com-1', 'cat-2', 'Pan de Masa Madre con Semillas Tostadas 650g', 'Fermentación lenta de 24 hs, corteza crocante y miga aireada. Perfecto para tostadas.', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800&auto=format&fit=crop&q=80', 3600, 2160, 40, 15, 8, '2026-10-05', 'Hoy hasta 20:00 hs', 0.65, 'Próximo a vencer', 'Horneado ayer por la tarde. Excelente textura para tostar o congelar en rebanadas.', 'activo', 'alta', 'Prioridad alta', 'Vence en 2 días. Calidad artesanal destacada de Tandil.', NULL),
('prod-27', 'com-1', 'cat-2', 'Pan Lactal Blanco Rodajas Gruesas 550g', 'Pan de molde tierno elaborado con harina pura y leche. Textura súper suave para tostadas o sándwiches.', 'https://images.unsplash.com/photo-1549931319-a545dcf3bc73?w=800&auto=format&fit=crop&q=80', 3100, 2015, 35, 22, 14, '2026-10-06', 'Hoy hasta 20:15 hs', 0.55, 'Próximo a vencer', 'Bolsa sellada con clip de fábrica. 3 días de vida útil óptima.', 'activo', 'media', 'Prioridad media', 'Ahorro del 35% en un producto infaltable del desayuno.', NULL),
('prod-28', 'com-1', 'cat-2', 'Pan de Hamburguesa con Sésamo Tostado x4 Unidades', 'Panes brioche tiernos con lluvia de semillas de sésamo dorado. Resisten salsas sin desarmarse.', 'https://images.unsplash.com/photo-1586190848861-99aa4a171e90?w=800&auto=format&fit=crop&q=80', 2400, 1440, 40, 20, 15, '2026-10-05', 'Hoy hasta 20:15 hs', 0.32, 'Baja rotación', 'Lote horneado hoy temprano que quedó de saldo al mediodía.', 'activo', 'alta', 'Prioridad alta', '40% OFF ideal para armar hamburguesas caseras esta noche.', NULL),
('prod-29', 'com-1', 'cat-2', 'Budín Casero Marmolado Vainilla y Cacao 350g', 'Budín artesanal con manteca y chocolate belga amargo. Baño de glasé suave de limón.', '/src/assets/images/budin_marmolado_entero_1791292684646.jpg', 3500, 1750, 50, 18, 11, '2026-10-05', 'Hoy hasta 20:15 hs', 0.35, 'Próximo a vencer', 'Elaborado hace 3 días. Miga esponjosa intacta; liquidación de fin de tanda.', 'activo', 'alta', 'Prioridad alta', 'Mitad de precio (50% OFF) para merienda dulce garantizada.', NULL),
('prod-6', 'com-5', 'cat-4', 'Cajón Familiar Frutillas Seleccionadas 1kg', 'Frutillas maduras súper dulces de Coronda. Ideales para licuados, mermeladas o postres.', 'https://images.unsplash.com/photo-1464965911861-746a04b4bca6?w=800&auto=format&fit=crop&q=80', 5200, 3120, 40, 20, 14, '2026-10-05', 'Hoy hasta 19:15 hs', 1, 'Próximo a vencer', 'Fruta madura de rotación inmediata para evitar merma total.', 'activo', 'alta', 'Prioridad alta', 'Fruta en su punto óptimo de aroma y azúcar natural.', NULL),
('prod-30', 'com-5', 'cat-4', 'Tomates Redondos Maduros de Huertistas 1.5kg', 'Tomates maduros de huertas locales de Tandil. Piel fina, jugosos y con sabor a tomate de campo.', '/src/assets/images/tomates_cajon_1791040527278.jpg', 3600, 1800, 50, 24, 16, '2026-10-05', 'Hoy hasta 19:15 hs', 1.5, 'Problema de presentación', 'Tomates muy maduros y con leves imperfecciones en la forma exterior. Pulpa deliciosa, ideales para salsa casera, gazpacho o ensaladas hoy.', 'activo', 'alta', 'Prioridad alta', '50% OFF para evitar descarte de producto cosechado en la región.', NULL),
('prod-31', 'com-5', 'cat-4', 'Bananas Seleccionadas de Ecuador 1kg', 'Bananas Cavendish de sabor concentrado. Máxima dulzura natural por maduración en racimo.', 'https://images.unsplash.com/photo-1571771894821-ce9b6c11b08e?w=800&auto=format&fit=crop&q=80', 3200, 1920, 40, 28, 20, '2026-10-05', 'Hoy hasta 19:15 hs', 1, 'Problema de presentación', 'Cáscara con pequeñas motas marrones por maduración avanzada. La pulpa interior está cremosa, firme, sana y dulce sin golpes.', 'activo', 'alta', 'Prioridad alta', '40% OFF ideal para comer en el día, licuados o budín de banana.', NULL),
('prod-32', 'com-5', 'cat-4', 'Manzanas Rojas Cripps Pink Tandil 1.5kg', 'Manzanas de fruta firme y crujiente con toque ácido y dulce. Aporte de fibra y vitaminas.', 'https://images.unsplash.com/photo-1560806887-1e4cd0b6cbd6?w=800&auto=format&fit=crop&q=80', 4100, 2870, 30, 25, 18, '2026-10-08', 'Hoy hasta 19:15 hs', 1.5, 'Problema de presentación', 'Calibre desparejo y pequeñas marcas superficiales en la piel por el viento serrano; pulpa crujiente 100% sana y dulce.', 'activo', 'media', 'Prioridad media', 'Fruta perfecta rechazada por estándares estéticos de cadenas comerciales.', NULL),
('prod-33', 'com-5', 'cat-4', 'Bolsa de Papas Negras Tandileras de Campo 2.5kg', 'Papa serrana recién cosechada de tierras altas de Tandil. Excelente rendimiento para puré, hervidas o fritas.', 'https://images.unsplash.com/photo-1518977676601-b53f82aba655?w=800&auto=format&fit=crop&q=80', 3800, 2850, 25, 35, 25, '2026-10-13', 'Hoy hasta 19:15 hs', 2.5, 'Baja rotación', 'Excedente de cosecha de productor local de Tandil. Papas enteras sin brotes.', 'activo', 'baja', 'Prioridad baja', '25% de ahorro en un tubérculo fundamental para la familia.', NULL),
('prod-34', 'com-5', 'cat-4', 'Lechuga Mantecosa Hidropónica x2 Plantas con Raíz', 'Cultivo hidropónico serrano libre de pesticidas. Hojas tiernas con raíz viva para prolongar su frescura.', 'https://images.unsplash.com/photo-1622206151226-18ca2c9ab4a1?w=800&auto=format&fit=crop&q=80', 2800, 1820, 35, 18, 12, '2026-10-05', 'Hoy hasta 19:15 hs', 0.4, 'Problema de presentación', 'Hojas exteriores de la base apenas rozadas en el cajón de cosecha; el corazón está 100% fresco, hidratado y crujiente.', 'activo', 'alta', 'Prioridad alta', 'Verdura verde hidropónica lista para ensaladas del mediodía y noche.', NULL),
('prod-4', 'com-4', 'cat-7', 'Ensalada César Gourmet con Pollo Grillado', 'Mix de hojas verdes, pollo marinado, croutons y aderezo césar. Frescura intacta para almuerzo o cena.', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=800&auto=format&fit=crop&q=80', 4800, 2400, 50, 12, 6, '2026-10-04', 'Hoy hasta 20:30 hs', 0.4, 'Próximo a vencer', 'Vianda fresca preparada hoy al mediodía para consumo durante la jornada.', 'activo', 'alta', 'Prioridad alta', 'Vianda fresca lista para consumir hoy. Descuento agresivo del 50%.', NULL)
